// Native structures, construction sessions, permission lists and item transfers.
class SwgxrHousing {
 using Json=JSONSerializationType;
 static std::string id(SceneObject* o){return o?std::to_string(o->getObjectID()):"0";}
 static uint64 oid(const Json& r,const char* key){auto v=r.at(key).get<std::string>();if(v.empty() || v.size()>20 || v.find_first_not_of("0123456789")!=std::string::npos)throw std::runtime_error("Invalid housing object");return std::stoull(v);}
 static String data(CreatureObject* c,const char* key){return c->getPlayerObject()->getScreenPlayData("swgxr_housing",key);}
 static void put(CreatureObject* c,const char* key,const Json& value){c->getPlayerObject()->setScreenPlayData("swgxr_housing",key,String(value.dump().c_str()));}
 static Json point(SceneObject* o){auto p=o->getWorldPosition();return Json::array({p.getX(),p.getZ(),p.getY()});}
 static Json record(SceneObject* o){auto q=o->getDirection();return {{"id",id(o)},{"template",std::string(o->getObjectTemplate()->getFullTemplateString().toCharArray())},{"position",point(o)},{"local_position",Json::array({o->getPositionX(),o->getPositionZ(),o->getPositionY()})},{"quaternion",Json::array({q->getX(),q->getY(),q->getZ(),q->getW()})},{"heading_radians",q->getRadians()}};}
 static void vector(const Json& p){if(!p.is_array() || p.size()!=3)throw std::runtime_error("Invalid housing position");for(auto& v:p)if(!v.is_number() || !std::isfinite(v.get<double>()) || std::abs(v.get<double>())>8192)throw std::runtime_error("Invalid housing position");}
 static StructureObject* terminalStructure(CreatureObject* c,const Json& r){auto t=c->getZoneServer()->getObject(oid(r,"terminal_id"));auto s=controlled(t);if(!s || t->getZone()!=c->getZone() || t->getParentID()!=c->getParentID() || !c->isInRange(t,8) || !CollisionManager::checkLineOfSight(c,t))throw std::runtime_error("House terminal out of reach");return s;}
public:
 static Json furnish(CreatureObject* c,const Json& r,bool recover,bool shipLocal=false){
  ManagedReference<SceneObject*> parent=c->getParent().get();SceneObject* root=c->getRootParent();if(!parent || !parent->isCellObject() || !root || !(shipLocal?root->isPobShip() && root->asPobShip()->isOnAdminList(c):root->isBuildingObject() && static_cast<BuildingObject*>(root)->isOnAdminList(c)))throw std::runtime_error("Enter a house where you have administrator permission");
  auto o=c->getZoneServer()->getObject(oid(r,"item_id"));if(!o || o->isVendor() || o->isCreatureObject() || o->isTerminal() || root->containsChildObject(o))throw std::runtime_error("Movable furniture required");Locker lock(o,c);
  auto cell=static_cast<CellObject*>(parent.get());
  if(recover){if(o->getParentID()!=parent->getObjectID() || !c->isInRange(o,3) || !CollisionManager::checkLineOfSight(c,o))throw std::runtime_error("Furniture out of reach");for(auto field:{"left_hand","right_hand"}){auto p=r.at(field);vector(p);auto op=shipLocal?o->getPosition():o->getWorldPosition();Vector3 hand(p[0].get<float>(),p[2].get<float>(),p[1].get<float>());auto playerPosition=shipLocal?c->getPosition():c->getWorldPosition();if(hand.distanceTo(playerPosition)>3.0f)throw std::runtime_error("Furniture hand out of reach");auto appearance=o->getAppearanceTemplate();auto volume=appearance?appearance->getBoundingVolume():nullptr;bool touching=false;if(volume){Matrix4 rotation;rotation.setRotationMatrix(o->getDirection()->toMatrix3());auto local=CollisionManager::getAxisAlignedVector(hand-op,rotation);const auto& box=volume->getBoundingBox();const auto low=box.getMinBound(),high=box.getMaxBound();touching=local.getX()>=low->getX()-.2f && local.getX()<=high->getX()+.2f && local.getY()>=low->getY()-.2f && local.getY()<=high->getY()+.2f && local.getZ()>=low->getZ()-.2f && local.getZ()<=high->getZ()+.2f;}else touching=hand.distanceTo(op)<=1.0f;if(!touching)throw std::runtime_error("Both hands must touch the item");}}
  else if(!SwgxrEquipment::inInventory(o,c))throw std::runtime_error("Owned inventory item required");
  float x=0,y=0,z=0;Json q;
  if(!recover){auto p=r.at("placement_position");vector(p);auto wp=shipLocal?c->getPosition():c->getWorldPosition();if(Vector3(p[0].get<float>(),p[2].get<float>(),p[1].get<float>()).distanceTo(wp)>3)throw std::runtime_error("Place furniture within hand reach");double a=root->getDirection()->getRadians(),dx=p[0].get<double>()-root->getPositionX(),dy=p[2].get<double>()-root->getPositionY();x=dx*std::cos(a)-dy*std::sin(a);y=dx*std::sin(a)+dy*std::cos(a);z=p[1].get<float>()-root->getPositionZ();if(shipLocal){x=p[0].get<float>();z=p[1].get<float>();y=p[2].get<float>();}
   std::unique_ptr<Vector<float>> floors(CollisionManager::getCellFloorCollision(x,y,cell));bool supported=false;float floorZ=-100000;if(floors)for(int i=0;i<floors->size();++i)if(floors->get(i)<=z+.1 && floors->get(i)>floorZ){floorZ=floors->get(i);supported=true;}if(!supported)throw std::runtime_error("Release inside the current house cell");
   Vector3 endpoint(x,y,z);if(!CollisionManager::checkLineOfSightInParentCell(c,endpoint))throw std::runtime_error("Furniture position obstructed");if(!r.value("suspended",false))z=floorZ;
   q=r.at("local_quaternion");if(!q.is_array() || q.size()!=4)throw std::runtime_error("Invalid furniture orientation");double norm=0;for(auto& v:q){if(!v.is_number() || !std::isfinite(v.get<double>()))throw std::runtime_error("Invalid furniture orientation");norm+=v.get<double>()*v.get<double>();}if(std::abs(norm-1)>.01)throw std::runtime_error("Unit furniture orientation required");
  }
  SceneObject* dest=recover?c->getInventory().get():parent.get();auto cmd=c->getZoneServer()->getObjectController()->getQueueCommand("transferitemmisc");auto args=id(dest)+" -1 0 0 0";if(!cmd || cmd->doQueueCommand(c,o->getObjectID(),UnicodeString(String(args.c_str())))!=QueueCommand::SUCCESS || o->getParentID()!=dest->getObjectID())throw std::runtime_error("Core3 furniture transfer rejected: permissions or item limit");
  if(!recover){o->initializePosition(x,z,y);o->setDirection(q[3].get<float>(),q[0].get<float>(),q[1].get<float>(),q[2].get<float>());o->updateZoneWithParent(parent,true);}o->updateToDatabaseAllObjects(false);return record(o);
 }
public:
 static StructureObject* controlled(SceneObject* o){if(!o || !o->isTerminal() || !o->getObjectTemplate()->getFullTemplateString().contains("/terminal_player_structure"))return nullptr;SceneObject* s=static_cast<Terminal*>(o)->getControlledObject();return s && s->isStructureObject()?static_cast<StructureObject*>(s):nullptr;}
 static void describe(CreatureObject* c,SceneObject* t,Json& view){auto s=controlled(t);if(!s)return;view["structure_id"]=id(s);view["owner"]=s->isOwnerOf(c);view["maintenance"]=s->getSurplusMaintenance();view["maintenance_rate"]=s->getMaintenanceRate();view["options"]=Json::array();if(s->isOnAdminList(c))view["options"].push_back({{"id","deposit"},{"name","Deposit upkeep credits"},{"description","Maintenance: "+std::to_string(s->getSurplusMaintenance())+" credits"}});if(s->isOwnerOf(c))for(auto list:{"ENTRY","ADMIN","BAN","VENDOR"})for(auto op:{"add","remove"})view["options"].push_back({{"id",std::string(op)+"_"+list},{"name",std::string(op)+" "+list+" permission"},{"description","Select, then shake hands with the target within one minute."},{"permission_list",list},{"permission_action",op}});if(s->isBuildingObject()){auto b=static_cast<BuildingObject*>(s);view["item_count"]=b->getCurrentNumberOfPlayerItems();view["item_limit"]=b->getMaximumNumberOfPlayerItems();}}
 static Json snapshot(CreatureObject* c){
  Json out={{"structures",Json::array()},{"items",Json::array()},{"construction_active",c->containsActiveSession(SessionFacadeType::PLACESTRUCTURE)}};SortedVector<ManagedReference<TreeEntry*>> objects;c->getZone()->getInRangeObjects(c->getWorldPosition().getX(),c->getWorldPosition().getZ(),c->getWorldPosition().getY(),256,&objects,true,false);
  for(int i=0;i<objects.size() && out["structures"].size()<64;++i){auto o=static_cast<SceneObject*>(objects.get(i).get());if(o && o->isStructureObject() && static_cast<StructureObject*>(o)->getOwnerObjectID()!=0){if((SwgxrHarvesters::supports(o) || SwgxrFactories::supports(o)) && static_cast<StructureObject*>(o)->getDeedObjectID()==0)continue;auto row=record(o);SwgxrTerrainModification::describe(o,row);row["harvester"]=SwgxrHarvesters::supports(o);row["factory"]=SwgxrFactories::supports(o);row["admin"]=static_cast<StructureObject*>(o)->isOnAdminList(c);row["owner_id"]=std::to_string(static_cast<StructureObject*>(o)->getOwnerObjectID());out["structures"].push_back(row);}}
  out["blueprints"]=SwgxrFactories::blueprints(c);out["deeds"]=Json::array();SwgxrFactories::deeds(c,c->getInventory(),out["deeds"]);SwgxrHarvesters::deeds(c,c->getInventory(),out["deeds"]);for(int i=0;i<c->getSlottedObjectsSize();++i){auto bag=c->getSlottedObject(i);if(bag && bag->isWearableContainerObject()){SwgxrHarvesters::deeds(c,bag,out["deeds"]);SwgxrFactories::deeds(c,bag,out["deeds"]);}}
  ManagedReference<SceneObject*> parent=c->getParent().get();SceneObject* root=c->getRootParent();if(parent && parent->isCellObject() && root && root->isBuildingObject()){auto b=static_cast<BuildingObject*>(root);out["item_count"]=b->getCurrentNumberOfPlayerItems();out["item_limit"]=b->getMaximumNumberOfPlayerItems();out["can_furnish"]=b->isOnAdminList(c);for(int ci=1;ci<=b->getTotalCellNumber();++ci){auto cell=b->getCell(ci);if(!cell)continue;for(int i=0;i<cell->getContainerObjectsSize() && out["items"].size()<1000;++i){auto o=cell->getContainerObject(i);if(!o || !o->isTangibleObject() || o->isCreatureObject() || o->isVendor())continue;auto row=record(o);row["building_id"]=id(b);row["cell_index"]=ci;row["terminal"]=o->isTerminal();row["recoverable"]=!o->isTerminal() && !o->isClientObject() && o->checkContainerPermission(c,ContainerPermissions::MOVECONTAINER) && cell->checkContainerPermission(c,ContainerPermissions::MOVEOUT);out["items"].push_back(row);}}}return out;
 }
 static Json run(CreatureObject* c,const Json& r){
  auto action=r.at("action").get<std::string>();bool mutation=action!="house_status" && action!="house_preview" && action!="house_harvester_status" && action!="house_factory_status";Json result={{"success",true}},proposal=r,receipts=Json::array();for(auto f:{"position","building_id","cell_index","zone","request_id","left_hand","right_hand"})proposal.erase(f);auto saved=data(c,"receipts");if(!saved.isEmpty())receipts=Json::parse(saved.toCharArray());auto key=r.value("request_id",std::string());bool replay=false;
  if(mutation){if(key.size()<8 || key.size()>64)throw std::runtime_error("Stable housing request ID required");for(auto& receipt:receipts)if(receipt["id"]==key){if(receipt["request"]!=proposal)throw std::runtime_error("Housing request ID reused");result=receipt["result"];result["replayed"]=true;replay=true;break;}}
  if(!replay){SwgxrMovement::move(c,r);if(action!="house_status" && (c->isDead() || c->isIncapacitated() || c->isRidingMount() || c->isInCombat()))throw std::runtime_error("Housing unavailable in current state");
   if(action=="house_preview" || action=="house_place"){auto p=r.at("placement_position");vector(p);int angle=r.at("rotation").get<int>();if(angle<0 || angle>3)throw std::runtime_error("Quarter turn required");auto cmd=dynamic_cast<const PlaceStructureCommand*>(c->getZoneServer()->getObjectController()->getQueueCommand("placestructure"));if(!cmd)throw std::runtime_error("Native placement command unavailable");auto args=std::to_string(oid(r,"deed_id"))+" "+std::to_string(p[0].get<double>())+" "+std::to_string(p[2].get<double>())+" "+std::to_string(angle);bool valid=cmd->placement(c,UnicodeString(String(args.c_str())),action=="house_preview")==QueueCommand::SUCCESS;result["valid"]=valid;result["placement_position"]=p;result["rotation"]=angle;result["deed_id"]=r["deed_id"];result["reason"]=valid?"":"Core3 placement rules reject this location, deed or player state.";if(action=="house_place" && !valid)throw std::runtime_error("Core3 rejected structure placement");}
   else if(action=="house_deposit"){auto s=terminalStructure(c,r);Locker lock(s,c);int amount=r.at("amount").get<int>();if(!s->isOnAdminList(c) || amount<=0 || amount>c->getCashCredits() || amount>100000000-s->getSurplusMaintenance())throw std::runtime_error("Invalid maintenance deposit");auto before=c->getCashCredits();StructureManager::instance()->payMaintenance(s,c,amount);if(before-c->getCashCredits()!=amount)throw std::runtime_error("Maintenance payment rejected");s->updateToDatabaseAllObjects(false);}
   else if(action=="house_permission_arm"){auto s=terminalStructure(c,r);if(!s->isOwnerOf(c))throw std::runtime_error("Owner permission required");auto list=r.at("permission_list").get<std::string>(),op=r.at("permission_action").get<std::string>();if((list!="ENTRY" && list!="ADMIN" && list!="BAN" && list!="VENDOR") || (op!="add" && op!="remove"))throw std::runtime_error("Invalid house permission");Json arm={{"structure_id",id(s)},{"permission_list",list},{"permission_action",op},{"arm_id",key}};put(c,"arm",arm);c->addCooldown("swgxr_house_permission",60000);result["arm"]=arm;}
   else if(action=="house_permission"){if(c->checkCooldownRecovery("swgxr_house_permission") || data(c,"arm").isEmpty())throw std::runtime_error("Select house permission again; one minute expired");auto arm=Json::parse(data(c,"arm").toCharArray());if(arm.value("arm_id",std::string())!=r.value("arm_id",std::string()))throw std::runtime_error("House permission changed");auto s=c->getZoneServer()->getObject(oid(arm,"structure_id")).castTo<StructureObject*>();auto target=c->getZoneServer()->getObject(oid(r,"target_id")).castTo<CreatureObject*>();if(!s || !s->isOwnerOf(c) || !target || !target->isPlayerCreature() || target==c || c->getParentID()!=target->getParentID() || !c->isInRange(target,3) || !CollisionManager::checkLineOfSight(c,target))throw std::runtime_error("Owner and nearby handshake target required");auto cmd=dynamic_cast<const PermissionListModifyCommand*>(c->getZoneServer()->getObjectController()->getQueueCommand("permissionlistmodify"));if(!cmd || cmd->handleStructurePermissions(c,s,target->getFirstName(),String(arm["permission_list"].get<std::string>().c_str()),String(arm["permission_action"].get<std::string>().c_str()),"SWGXR handshake")!=QueueCommand::SUCCESS)throw std::runtime_error("Native permission change rejected");put(c,"arm",Json::object());s->updateToDatabaseAllObjects(false);}
   else if(action.rfind("house_factory_",0)==0)result.update(SwgxrFactories::execute(c,r));
   else if(action.rfind("house_harvester_",0)==0)result.update(SwgxrHarvesters::execute(c,r));
   else if(action=="house_drop" || action=="house_recover")result["item"]=furnish(c,r,action=="house_recover");else if(action!="house_status")throw std::runtime_error("Unknown housing action");
   if(mutation){result["request_id"]=key;receipts.push_back({{"id",key},{"request",proposal},{"result",result}});while(receipts.size()>64)receipts.erase(receipts.begin());put(c,"receipts",receipts);c->updateToDatabaseAllObjects(false);}
  }
  return {{"backend","core3"},{"source_kind","core3_services"},{"character_id",id(c)},{"housing",snapshot(c)},{"inventory",SwgxrInventory::snapshot(c)},{"mutation",result}};
 }
};
#endif
